    public function pool():void { global$wpdb;$rows=$wpdb->get_results('SELECT id,title,source_url,status FROM '.Support::table('feed_items').' ORDER BY id DESC LIMIT 100');$this->begin(__('News Pool','wordpress-news-bot'));$this->notice();if(!$rows){echo '<div class="wpnb-card"><p>'.esc_html__('No news items are waiting for review.','wordpress-news-bot').'</p></div>';$this->end();return;}echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_bulk_create_drafts');echo '<input type="hidden" name="action" value="wpnb_bulk_create_drafts"><table class="widefat striped"><thead><tr><th class="check-column"></th><th>'.esc_html__('Title','wordpress-news-bot').'</th><th>'.esc_html__('Status','wordpress-news-bot').'</th><th>'.esc_html__('Actions','wordpress-news-bot').'</th></tr></thead><tbody>';foreach($rows as$row){$eligible=in_array((string)$row->status,['new','review','error'],true);echo '<tr><th class="check-column">'.($eligible?'<input type="checkbox" name="item_ids[]" value="'.esc_attr((string)$row->id).'">':'').'</th><td><a href="'.esc_url((string)$row->source_url).'" target="_blank" rel="noopener noreferrer">'.esc_html((string)$row->title).'</a></td><td>'.esc_html((string)$row->status).'</td><td>';if($eligible){wp_nonce_field('wpnb_create_draft_'.(int)$row->id,'_wpnonce_'.(int)$row->id);echo '<button class="button wpnb-create-draft" type="submit" name="single_item_id" value="'.esc_attr((string)$row->id).'">'.esc_html__('Create Draft','wordpress-news-bot').'</button>';}echo '</td></tr>';}echo '</tbody></table><p><button class="button button-primary" type="submit">'.esc_html__('Create Selected Drafts','wordpress-news-bot').'</button></p></form>';$this->end(); }
    public function health():void { $this->requireManage();global$wpdb;$report=(new DatabaseHealth($wpdb))->inspect();$this->begin(__('System Health','wordpress-news-bot'));$this->notice();echo '<p>'.esc_html((new SecretStorage())->isSupported()?__('Secure encryption is available.','wordpress-news-bot'):__('Secure encryption is unavailable. API keys cannot be stored.','wordpress-news-bot')).'</p><div class="wpnb-card"><h2>'.esc_html__('Database Health','wordpress-news-bot').'</h2><p class="wpnb-status">'.esc_html($report['status']==='healthy'?__('Healthy','wordpress-news-bot'):__('Repair required','wordpress-news-bot')).'</p><p>'.esc_html(sprintf(__('Schema fingerprint: %s','wordpress-news-bot'),$report['fingerprint'])).'<br>'.esc_html(sprintf(__('Plugin/schema version: %1$s / %2$s','wordpress-news-bot'),WPNB_VERSION,WPNB_SCHEMA_VERSION)).'</p>';
        $engineIssues=array_values(array_filter($report['issues'],static fn(array$issue):bool=>($issue['code']??'')==='engine_mismatch'));$enginePreview=$engineIssues?(new DatabaseEngineRepair($wpdb))->preview():[];
        if($report['issues']){echo '<ul>';foreach($report['issues']as$issue)echo '<li>'.esc_html($this->healthIssue($issue)).'</li>';echo '</ul>';if($engineIssues){echo '<div class="notice notice-warning inline"><p><strong>'.esc_html__('WordPress News Bot tables will be converted from MyISAM to InnoDB. Existing data will be preserved. Only plugin tables will be affected.','wordpress-news-bot').'</strong></p><p>'.esc_html(sprintf(__('Preflight: %1$s, rows: %2$d, estimated size: %3$s','wordpress-news-bot'),$this->engineErrorMessage((string)$enginePreview['code']),(int)$enginePreview['total_rows'],size_format((int)$enginePreview['total_bytes']))).'</p></div>';}echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_repair_database');echo '<input type="hidden" name="action" value="wpnb_repair_database">';if($engineIssues)echo '<p><label><input type="checkbox" name="confirm_engine_conversion" value="1" required> '.esc_html__('I confirm the MyISAM to InnoDB conversion for WordPress News Bot tables.','wordpress-news-bot').'</label></p>';echo '<button class="button button-primary" '.($engineIssues&&in_array($enginePreview['code'],['innodb_unavailable','alter_permission_denied'],true)?'disabled':'').'>'.esc_html__('Repair Database','wordpress-news-bot').'</button></form>';}else{$pendingSource=(array)get_transient($this->sourceFormKey());if(!empty($pendingSource['token']))echo '<p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=wpnb-sources#wpnb-source-form')).'">'.esc_html__('Return to the verified source and save it','wordpress-news-bot').'</a></p>';}
        $safeReport=['status'=>$report['status'],'issues'=>$report['issues'],'schema_fingerprint'=>$report['fingerprint'],'plugin_version'=>WPNB_VERSION,'stored_schema'=>$report['stored_schema'],'expected_schema'=>$report['expected_schema'],'engine_preflight'=>$enginePreview,'engine_repair_state'=>DatabaseEngineRepair::state(),'generated_at'=>Support::now()];echo '<p><button type="button" class="button" onclick="navigator.clipboard.writeText(document.getElementById(\'wpnb-diagnostic-report\').value)">'.esc_html__('Copy Diagnostic Information','wordpress-news-bot').'</button></p><textarea id="wpnb-diagnostic-report" class="large-text code" rows="8" readonly>'.esc_textarea(Support::json($safeReport)).'</textarea></div>';
        $testId=sanitize_text_field(wp_unslash($_GET['test_id']??''));echo '<div class="wpnb-card"><h2>'.esc_html__('Diagnostics','wordpress-news-bot').'</h2><form method="get"><input type="hidden" name="page" value="wpnb-health"><label for="wpnb-test-id">'.esc_html__('Test ID','wordpress-news-bot').'</label> <input id="wpnb-test-id" name="test_id" value="'.esc_attr($testId).'" pattern="[a-fA-F0-9]{16,64}"> <button class="button">'.esc_html__('Search','wordpress-news-bot').'</button></form>';
        if($testId!==''){$record=DiagnosticStore::find($testId);if($record&&($record['db_code']??'')==='db_unknown'&&($record['operation']??'')==='schema_repair'&&$engineIssues){$record['db_code']='engine_conversion_required';$record['suggestion']=__('MyISAM to InnoDB conversion is required. Confirm and run Database Repair.','wordpress-news-bot');}if($record)echo '<pre>'.esc_html(Support::json($record)).'</pre>';else echo '<p>'.esc_html__('No safe diagnostic record was found for this Test ID.','wordpress-news-bot').'</p>';}echo '</div>';$this->automationCard();$this->end(); }
    public function repairDatabase():void { $this->requirePostAction('wpnb_repair_database');global$wpdb;$testId=bin2hex(random_bytes(8));$preview=(new DatabaseEngineRepair($wpdb))->preview();$approved=!empty($_POST['confirm_engine_conversion']);try{if($preview['code']==='engine_conversion_required'&&!$approved)throw new DatabaseEngineRepairException('engine_conversion_required',['suggestion'=>'Confirm the MyISAM to InnoDB conversion.']);$result=(new DatabaseRepair($wpdb))->run(false,$approved);if($result['status']!=='healthy'){DiagnosticStore::record($testId,'database',$result['code'],'schema_repair',['schema_fingerprint'=>$result['after'],'affected_rows'=>$result['changed'],'suggestion'=>'Review unresolved schema issues before retrying.']);$this->storeAdminNotice(sprintf(__('Test ID: %s','wordpress-news-bot'),$testId));$this->redirect('wpnb-health&test_id='.$testId,'db_repair_failed');}$this->redirect('wpnb-health','db_repaired');}catch(DatabaseEngineRepairException$e){DiagnosticStore::record($testId,'database',$e->resultCode,'schema_repair',$e->diagnostics+['schema_fingerprint'=>(new DatabaseHealth($wpdb))->inspect()['fingerprint']]);$this->storeAdminNotice($this->engineErrorMessage($e->resultCode).' '.sprintf(__('Test ID: %s','wordpress-news-bot'),$testId));$this->redirect('wpnb-health&test_id='.$testId,'db_repair_failed');}catch(\Throwable$e){$classified=DatabaseErrorClassifier::classify((string)($wpdb->last_error??''),(int)($wpdb->last_errno??0));DiagnosticStore::record($testId,'database',$classified['code'],'schema_repair',$classified+['schema_fingerprint'=>(new DatabaseHealth($wpdb))->inspect()['fingerprint']]);$this->storeAdminNotice(sprintf(__('Test ID: %s','wordpress-news-bot'),$testId));$this->redirect('wpnb-health&test_id='.$testId,'db_repair_failed');} }
