    private function storeAdminNotice(string$message):void { set_transient('wpnb_admin_notice_'.get_current_user_id(),sanitize_text_field($message),MINUTE_IN_SECONDS); }
    private function sourceFormKey():string { return 'wpnb_source_form_'.get_current_user_id(); }
    private function retainSourceForm(array$input):void { $input['id']=absint($_POST['source_id']??0);$state=(array)get_transient($this->sourceFormKey());$candidate=$input;$hashInput=$input;unset($hashInput['id']);if(!isset($state['input_hash'])||!hash_equals((string)$state['input_hash'],hash('sha256',Support::json($hashInput))))$state=[];$state['input']=$candidate;set_transient($this->sourceFormKey(),$state,10*MINUTE_IN_SECONDS); }
    private function verifiedSourceTest(array$input):?array { $state=(array)get_transient($this->sourceFormKey());$posted=sanitize_text_field(wp_unslash($_POST['source_test_token']??''));if($posted===''||empty($state['token'])||!hash_equals((string)$state['token'],$posted)||!hash_equals((string)($state['input_hash']??''),hash('sha256',Support::json($input))))return null;return isset($state['result'])&&is_array($state['result'])?$state['result']:null; }
    private function sourceTestResult(array$result):void { $latest=(string)($result['last_item_date']??'');echo '<div class="notice notice-success inline"><p><strong>'.esc_html__('Connection test succeeded.','wordpress-news-bot').'</strong><br>'.esc_html(sprintf(__('Feed type: %s','wordpress-news-bot'),$result['feed_type']??'')).'<br>'.esc_html(sprintf(__('Items found: %d','wordpress-news-bot'),(int)($result['item_count']??0))).'<br>'.esc_html(sprintf(__('Latest item date: %s','wordpress-news-bot'),$latest!==''?$latest:__('Not provided','wordpress-news-bot'))).'<br>'.esc_html(sprintf(__('HTTP status: %d','wordpress-news-bot'),(int)($result['http_status']??0))).'<br>'.esc_html(sprintf(__('Response time: %d ms','wordpress-news-bot'),(int)($result['duration_ms']??0))).'<br>'.esc_html(sprintf(__('Final host: %s','wordpress-news-bot'),$result['final_host']??'')).'</p></div>'; }
    private function sourceErrorMessage(string$code):string { return match($code){'url_invalid','host_invalid','dns_failed','ip_blocked','redirect_blocked'=>__('The source did not pass the security check. Check the RSS URL and redirect domains.','wordpress-news-bot'),'http_failed'=>__('The source server could not be reached. Please try again.','wordpress-news-bot'),'http_status_invalid'=>__('The source returned an invalid HTTP response.','wordpress-news-bot'),'content_type_invalid','feed_invalid'=>__('The response is not in RSS/Atom format.','wordpress-news-bot'),'body_empty'=>__('The source returned an empty response.','wordpress-news-bot'),'body_too_large'=>__('The source response is too large.','wordpress-news-bot'),'xml_invalid'=>__('The source XML could not be parsed.','wordpress-news-bot'),'database_schema_invalid'=>__('The physical database schema requires repair before this source can be saved.','wordpress-news-bot'),'database_failed'=>__('The source could not be saved to the database.','wordpress-news-bot'),default=>__('The source could not be processed. Check the RSS URL and try again.','wordpress-news-bot')}; }
    private function handleSourceDiagnostic(SourceTestException$e,string$event):never { $this->logSourceError($event,$e);$this->storeAdminNotice($this->sourceErrorMessage($e->resultCode).' '.sprintf(__('Test ID: %s','wordpress-news-bot'),$e->testId));if(in_array($e->resultCode,['database_schema_invalid','database_failed'],true))$this->redirect('wpnb-health&test_id='.$e->testId,'db_repair_required');$this->redirect('wpnb-sources','source_diagnostic_error'); }
    private function logSourceError(string$event,\Throwable$e):void { global$wpdb;$context=['exception_class'=>get_class($e),'error_code'=>(int)$e->getCode()];if($e instanceof SourceTestException){$context+=['result_code'=>$e->resultCode,'test_id'=>$e->testId]+$e->diagnostics;if(in_array($e->resultCode,['database_schema_invalid','database_failed'],true))DiagnosticStore::record($e->testId,'database',(string)($e->diagnostics['db_code']??'db_unknown'),(string)($e->diagnostics['operation']??'source_write'),$e->diagnostics);}$wpdb->insert(Support::table('logs'),['level'=>'error','event'=>$event,'message'=>'A source administration operation failed.','context_json'=>Support::json(Security::cleanLogContext($context)),'created_at'=>Support::now()]); }
    private function healthIssue(array$issue):string { $label=match((string)($issue['code']??'')){'table_missing'=>__('A plugin database table is missing.','wordpress-news-bot'),'column_missing'=>__('A required database column is missing.','wordpress-news-bot'),'column_type_mismatch','column_nullability_mismatch','column_default_mismatch','column_extra_mismatch'=>__('A database column definition does not match.','wordpress-news-bot'),'index_missing'=>__('A required database index is missing.','wordpress-news-bot'),'index_mismatch'=>__('A database index definition does not match.','wordpress-news-bot'),'engine_mismatch'=>__('A plugin table is not using InnoDB.','wordpress-news-bot'),'collation_mismatch'=>__('A plugin table charset or collation does not match WordPress.','wordpress-news-bot'),'schema_version_mismatch'=>__('The recorded schema version does not match.','wordpress-news-bot'),default=>__('Database metadata could not be verified.','wordpress-news-bot')};$parts=[$label];foreach(['table','column','index']as$key)if(isset($issue[$key]))$parts[]=sanitize_key((string)$issue[$key]);return implode(' | ',$parts); }
    private function engineErrorMessage(string$code):string{return match($code){'innodb_unavailable'=>__('InnoDB is not available on this database server. Contact your hosting provider.','wordpress-news-bot'),'alter_permission_denied'=>__('The WordPress database user does not have permission to convert plugin tables.','wordpress-news-bot'),'engine_conversion_required'=>__('Confirm the MyISAM to InnoDB conversion before continuing.','wordpress-news-bot'),'engine_conversion_failed'=>__('The engine conversion stopped safely at the first failed table. Run repair again after resolving the reported condition.','wordpress-news-bot'),default=>__('Database engine repair could not be completed.','wordpress-news-bot')};}
    private function takeAdminNotice():string { $key='wpnb_admin_notice_'.get_current_user_id();$message=(string)get_transient($key);delete_transient($key);return $message; }
    private function redirect(string$page,string$notice=''):never { $url=admin_url('admin.php?page='.$page.($notice?'&wpnb_notice='.$notice:''));wp_safe_redirect($url);exit; }
}
